Lemma bv_extract_0_64 : forall v : word, bv_extract 0 64 v = v.
Proof. intros v. apply bv_eq. rewrite bv_extract_unsigned, Z.shiftr_0_r. apply bv_wrap_small. apply bv_unsigned_in_range. Qed.

(* [comment removed for export] *)
Lemma land_lxor7_zero : forall a b, 0 <= a -> 0 <= b -> Z.land (Z.lxor a b) 7 = 0 -> a mod 8 = b mod 8.
Proof.
  intros a b Ha Hb H. change 8 with (2^3).
  apply Z.bits_inj'. intros i Hi.
  destruct (Z.lt_ge_cases i 3) as [Hi3|Hi3].
  - rewrite !Z.mod_pow2_bits_low by lia.
    assert (T : Z.testbit (Z.land (Z.lxor a b) 7) i = false) by (rewrite H; apply Z.bits_0).
    rewrite Z.land_spec, Z.lxor_spec in T. change 7 with (Z.ones 3) in T. rewrite Z.ones_spec_low in T by lia.
    rewrite andb_true_r in T. destruct (Z.testbit a i), (Z.testbit b i); cbn in T; congruence.
  - rewrite !Z.mod_pow2_bits_high by lia. reflexivity.
Qed.

Lemma aligned_apart8 : forall d s, 0 <= d -> d < s -> Z.land (Z.lxor s d) 7 = 0 -> d + 8 <= s.
Proof.
  intros d s Hd Hl H. pose proof (land_lxor7_zero s d ltac:(lia) Hd H) as E.
  Z.div_mod_to_equations. nia.
Qed.

Lemma land64_mod : forall x, Z.land x 18446744073709551615 = x mod 2^64.
Proof. intros x. change 18446744073709551615 with (Z.ones 64). apply Z.land_ones. lia. Qed.

Lemma b8_of_byte : forall b : byte, b8 (bv_unsigned b) = b.
Proof. intros b. pose proof (Z_to_bv8_low b 0 ltac:(lia)) as E. rewrite Z.mul_0_r, Z.add_0_r in E. exact E. Qed.

