  Lemma mm_tail : forall (i dc sc : Z) (xa2 : word) m junk x5 x11 x15 x16 x17 x28,
    xa2 = Z_to_bv 64 (N - i) ->
    dc = Dst + i -> sc = Src + i -> 0 <= i <= N ->
    rw_cells rsegs m Dst [CB (Z.to_nat i) (firstn (Z.to_nat i) src)] ->
    rw_cells rsegs m dc [CB (Z.to_nat (N - i)) junk] ->
    ro_cells rsegs m sc [CB (Z.to_nat (N - i)) (skipn (Z.to_nat i) src)] ->
    mem_inv rsegs m -> munch W m0 m -> wmono rsegs m0 m ->
    bv_unsigned ra mod 2 = 0 ->
    evt rsegs POST (ST 0x75658 m x5 x11 xa2 (Z_to_bv 64 dc) (Z_to_bv 64 sc) x15 x16 x17 x28).
